"use client"

import { useEffect, useRef, useState, type UIEvent } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/cn"

import { compileShader, mountGlLoop, type GlContext, type GlLoopHandle, type GlSize } from "./gl/gl-loop"

/** original implementation. Cards bend with this gallery's own scroll speed. */

const FULL_PX_PER_MS = 2
const HALF_LIFE_MS = 80
const DEFAULT_SPEED = 1
const DEFAULT_INTENSITY = 0.6
const DEFAULT_GAP = 16

export interface GalleryBend {
  bend: number
  fringe: number
}

export interface VelocityBendGalleryProps {
  speed?: number
  intensity?: number
  gap?: number
  images?: readonly string[]
  className?: string
}

const TITLES = ["North aisle", "South aisle", "East court", "West stair"] as const
const TONES = ["--primary", "--chart-2", "--chart-4", "--primary"] as const

interface CardModel {
  title: string
  tone: string
  src?: string
}

interface StripCard extends CardModel {
  picture: Picture
}

type Picture = "pending" | "procedural" | "photo"

interface Tuning {
  rate: number
  amount: number
  spacing: number
  still: boolean
}

interface GalleryGpu {
  program: WebGLProgram
  texture: WebGLTexture
  paint: HTMLCanvasElement
  key: string
  tex: WebGLUniformLocation | null
  scroll: WebGLUniformLocation | null
  span: WebGLUniformLocation | null
  bend: WebGLUniformLocation | null
  fringe: WebGLUniformLocation | null
}

function gallerySpeed(speed: number) {
  if (!Number.isFinite(speed)) return DEFAULT_SPEED
  if (speed < 0.25) return 0.25
  if (speed > 2.5) return 2.5
  return speed
}

function galleryIntensity(intensity: number) {
  if (!Number.isFinite(intensity)) return 0
  if (intensity < 0) return 0
  if (intensity > 1) return 1
  return intensity
}

function galleryGap(gap: number) {
  if (!Number.isFinite(gap)) return DEFAULT_GAP
  if (gap < 0) return 0
  if (gap > 48) return 48
  return gap
}

/** 2 px/ms at speed 1 and intensity 1 is a full bend. Fringe is half of |bend|. */
export function galleryBend(deltaPx: number, deltaMs: number, speed: number, intensity: number): GalleryBend {
  const amount = galleryIntensity(intensity)
  if (!Number.isFinite(deltaPx) || !Number.isFinite(deltaMs) || deltaMs <= 0 || amount === 0) {
    return { bend: 0, fringe: 0 }
  }
  const scaled = (deltaPx / deltaMs) * gallerySpeed(speed)
  const bend = Math.max(-1, Math.min(1, scaled / FULL_PX_PER_MS)) * amount
  return { bend, fringe: Math.abs(bend) * 0.5 }
}

/** speed 1 halves the remaining bend every 80ms. */
export function settleBend(bend: number, dtMs: number, speed: number): number {
  if (!Number.isFinite(bend) || bend === 0) return 0
  if (!Number.isFinite(dtMs) || dtMs <= 0) return bend
  const next = bend * 0.5 ** ((dtMs * gallerySpeed(speed)) / HALF_LIFE_MS)
  if (Math.abs(next) < 0.001) return 0
  return next
}

function cardsOf(images: readonly string[] | undefined): CardModel[] {
  if (!images || images.length === 0) {
    return TITLES.map((title, index) => ({ title, tone: TONES[index] ?? "--primary" }))
  }
  return images.map((src, index) => ({
    title: TITLES[index % TITLES.length] ?? "North aisle",
    tone: TONES[index % TONES.length] ?? "--primary",
    src,
  }))
}

function cardPicture(src: string | undefined, loaded: ReadonlySet<string>, failed: ReadonlySet<string>): Picture {
  if (!src || failed.has(src)) return "procedural"
  if (loaded.has(src)) return "photo"
  return "pending"
}

function galleryPicture(cards: readonly CardModel[], loaded: ReadonlySet<string>, failed: ReadonlySet<string>): Picture {
  let photo = false
  let pending = false
  for (const card of cards) {
    const picture = cardPicture(card.src, loaded, failed)
    if (picture === "pending") pending = true
    if (picture === "photo") photo = true
  }
  if (pending) return "pending"
  if (photo) return "photo"
  return "procedural"
}

function token(style: CSSStyleDeclaration, name: string, fallback: string) {
  const value = style.getPropertyValue(name).trim()
  if (value.length === 0 || value.includes("var(")) return fallback
  return value
}

function remember(set: ReadonlySet<string>, value: string) {
  if (set.has(value)) return set
  const next = new Set(set)
  next.add(value)
  return next
}

function galleryShaders(webgl2: boolean) {
  const vert = webgl2
    ? "#version 300 es\nin vec2 a;\nout vec2 vUv;\nvoid main(){vUv=a*0.5+0.5;gl_Position=vec4(a,0.0,1.0);}"
    : "attribute vec2 a;\nvarying vec2 vUv;\nvoid main(){vUv=a*0.5+0.5;gl_Position=vec4(a,0.0,1.0);}"
  const head = webgl2
    ? "#version 300 es\nprecision highp float;\nin vec2 vUv;\nout vec4 frag;\n#define TEX texture\n#define WRITE frag\n"
    : "precision mediump float;\nvarying vec2 vUv;\n#define TEX texture2D\n#define WRITE gl_FragColor\n"
  const frag = `${head}
uniform sampler2D uTex;
uniform float uScroll;
uniform float uSpan;
uniform float uBend;
uniform float uFringe;
void main() {
  float span = clamp(uSpan, 0.05, 1.0);
  float v = clamp(uScroll * (1.0 - span) + vUv.y * span, 0.0, 1.0);
  float y = vUv.y - 0.5;
  float x = clamp(vUv.x + uBend * y * y * 0.35 - uBend * 0.08, 0.0, 1.0);
  vec2 uv = vec2(x, v);
  float shift = uFringe * 0.04;
  float r = TEX(uTex, vec2(clamp(uv.x + shift, 0.0, 1.0), uv.y)).r;
  float g = TEX(uTex, uv).g;
  float b = TEX(uTex, vec2(clamp(uv.x - shift, 0.0, 1.0), uv.y)).b;
  WRITE = vec4(r, g, b, TEX(uTex, uv).a);
}
`
  return { vert, frag }
}

function linkGallery(gl: GlContext) {
  const source = galleryShaders("drawBuffers" in gl)
  const program = gl.createProgram()
  if (!program) return null
  const vertex = compileShader(gl, gl.VERTEX_SHADER, source.vert)
  const fragment = compileShader(gl, gl.FRAGMENT_SHADER, source.frag)
  if (!vertex || !fragment) {
    if (vertex) gl.deleteShader(vertex)
    if (fragment) gl.deleteShader(fragment)
    gl.deleteProgram(program)
    return null
  }
  gl.bindAttribLocation(program, 0, "a")
  gl.attachShader(program, vertex)
  gl.attachShader(program, fragment)
  gl.linkProgram(program)
  gl.deleteShader(vertex)
  gl.deleteShader(fragment)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program)
    return null
  }
  return program
}

function bootGallery(gl: GlContext): GalleryGpu | null {
  const program = linkGallery(gl)
  const texture = gl.createTexture()
  if (!program || !texture) {
    if (program) gl.deleteProgram(program)
    if (texture) gl.deleteTexture(texture)
    return null
  }
  const paint = document.createElement("canvas")
  paint.width = 256
  paint.height = 640
  return {
    program,
    texture,
    paint,
    key: "",
    tex: gl.getUniformLocation(program, "uTex"),
    scroll: gl.getUniformLocation(program, "uScroll"),
    span: gl.getUniformLocation(program, "uSpan"),
    bend: gl.getUniformLocation(program, "uBend"),
    fringe: gl.getUniformLocation(program, "uFringe"),
  }
}

function upload(gl: GlContext, texture: WebGLTexture, source: HTMLCanvasElement) {
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, 1)
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source)
}

function loadedPhoto(host: HTMLElement, src: string) {
  for (const node of host.querySelectorAll("img")) {
    if (!(node instanceof HTMLImageElement)) continue
    if (node.getAttribute("src") !== src) continue
    if (node.complete && node.naturalWidth > 0) return node
  }
  return null
}

function paintStrip(canvas: HTMLCanvasElement, host: HTMLElement, cards: readonly StripCard[], gap: number) {
  const ctx = canvas.getContext("2d")
  if (!ctx || cards.length === 0) return false
  const width = 256
  const cardH = 160
  const raw = cards.length * cardH + (cards.length - 1) * gap
  const height = Math.min(2048, Math.max(1, Math.round(raw)))
  const scale = raw > 0 ? height / raw : 1
  canvas.width = width
  canvas.height = height
  const style = getComputedStyle(host)
  const background = token(style, "--background", "#f4f1ea")
  const foreground = token(style, "--foreground", "#1c1917")
  ctx.fillStyle = background
  ctx.fillRect(0, 0, width, height)
  let y = 0
  const drawnH = cardH * scale
  const drawnGap = gap * scale
  for (let index = 0; index < cards.length; index += 1) {
    const card = cards[index]
    if (!card) continue
    ctx.fillStyle = token(style, card.tone, index % 2 === 0 ? "#334155" : "#0f766e")
    ctx.fillRect(0, y, width, drawnH)
    const photo = card.picture === "photo" && card.src ? loadedPhoto(host, card.src) : null
    if (photo) {
      try {
        ctx.drawImage(photo, 0, y, width, drawnH)
      } catch {
        ctx.fillStyle = background
        ctx.fillRect(width * 0.12, y + drawnH * 0.18, width * 0.28, drawnH * 0.46)
      }
    }
    ctx.fillStyle = foreground
    ctx.font = "16px sans-serif"
    ctx.fillText(card.title, 16, y + drawnH * 0.82)
    y += drawnH + drawnGap
  }
  return true
}

function scrollSlice(el: HTMLElement) {
  const total = el.scrollHeight
  const view = el.clientHeight
  const span = total > 0 ? Math.min(1, Math.max(0.05, view / total)) : 1
  const max = Math.max(0, total - view)
  const scroll = max <= 0 ? 0 : el.scrollTop / max
  return { scroll, span }
}

function drawGallery(
  gl: GlContext,
  gpu: GalleryGpu,
  size: GlSize,
  host: HTMLElement,
  scroller: HTMLElement,
  cards: readonly StripCard[],
  gap: number,
  bend: number,
  fringe: number,
  draw: () => void,
) {
  const key = `${gap}|${cards.map((card) => `${card.picture}:${card.src ?? ""}:${card.title}`).join("|")}`
  if (gpu.key !== key) {
    try {
      if (!paintStrip(gpu.paint, host, cards, gap)) return
      upload(gl, gpu.texture, gpu.paint)
      gpu.key = key
    } catch {
      gpu.key = ""
      return
    }
  }
  const slice = scrollSlice(scroller)
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.viewport(0, 0, size.width, size.height)
  gl.useProgram(gpu.program)
  gl.activeTexture(gl.TEXTURE0)
  gl.bindTexture(gl.TEXTURE_2D, gpu.texture)
  gl.uniform1i(gpu.tex, 0)
  gl.uniform1f(gpu.scroll, slice.scroll)
  gl.uniform1f(gpu.span, slice.span)
  gl.uniform1f(gpu.bend, bend)
  gl.uniform1f(gpu.fringe, fringe)
  draw()
}

export function VelocityBendGallery({
  speed = DEFAULT_SPEED,
  intensity = DEFAULT_INTENSITY,
  gap = DEFAULT_GAP,
  images,
  className,
}: VelocityBendGalleryProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = useRef<HTMLDivElement>(null)
  const scrollerRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const bendRef = useRef(0)
  const fringeRef = useRef(0)
  const lastTop = useRef(0)
  const lastTime = useRef(0)
  const [blocked, setBlocked] = useState(false)
  const [scrollPx, setScrollPx] = useState(0)
  const [bendText, setBendText] = useState("0")
  const [loaded, setLoaded] = useState<ReadonlySet<string>>(() => new Set())
  const [failed, setFailed] = useState<ReadonlySet<string>>(() => new Set())
  const cards = cardsOf(images)
  const spacing = galleryGap(gap)
  const picture = galleryPicture(cards, loaded, failed)
  const still = reduced || blocked
  const tuningRef = useRef<Tuning>({ rate: DEFAULT_SPEED, amount: DEFAULT_INTENSITY, spacing: DEFAULT_GAP, still: false })
  const cardsRef = useRef<StripCard[]>([])

  useEffect(() => {
    const next = cardsOf(images)
    tuningRef.current = { rate: gallerySpeed(speed), amount: galleryIntensity(intensity), spacing, still }
    cardsRef.current = next.map((card) => ({ ...card, picture: cardPicture(card.src, loaded, failed) }))
  }, [failed, images, intensity, loaded, spacing, speed, still])

  useEffect(() => {
    if (reduced) return
    const canvas = canvasRef.current
    const host = hostRef.current
    const scroller = scrollerRef.current
    if (!canvas || !host || !scroller) return
    let gone = false
    let gpu: GalleryGpu | null = null
    let handle: GlLoopHandle | null = null
    handle = mountGlLoop(canvas, {
      host,
      frame: ({ gl, dt, size }) => {
        if (gone || !handle) return
        if (!gpu) {
          gpu = bootGallery(gl)
          if (!gpu) {
            gone = true
            handle.dispose()
            setBlocked(true)
            return
          }
        }
        const tuning = tuningRef.current
        if (tuning.still) return
        drawGallery(gl, gpu, size, host, scroller, cardsRef.current, tuning.spacing, bendRef.current, fringeRef.current, () => {
          handle?.draw()
        })
        const next = settleBend(bendRef.current, dt * 1000, tuning.rate)
        bendRef.current = next
        fringeRef.current = Math.abs(next) * 0.5
      },
    })
    if (!handle) {
      setBlocked(true)
      return
    }
    return () => {
      gone = true
      if (gpu) {
        handle?.gl.deleteProgram(gpu.program)
        handle?.gl.deleteTexture(gpu.texture)
      }
      handle?.dispose()
    }
  }, [reduced])

  function onScroll(event: UIEvent<HTMLDivElement>) {
    const top = event.currentTarget.scrollTop
    setScrollPx(top)
    if (tuningRef.current.still) {
      bendRef.current = 0
      fringeRef.current = 0
      lastTop.current = top
      lastTime.current = 0
      return
    }
    const now = performance.now()
    const deltaMs = lastTime.current === 0 ? 0 : now - lastTime.current
    const next = galleryBend(top - lastTop.current, deltaMs, tuningRef.current.rate, tuningRef.current.amount)
    lastTop.current = top
    lastTime.current = now
    bendRef.current = next.bend
    fringeRef.current = next.fringe
    setBendText(String(next.bend))
  }

  return (
    <div
      ref={hostRef}
      data-slot="velocity-bend-gallery"
      data-bend={still ? "0" : bendText}
      data-scroll={String(Math.round(scrollPx))}
      data-gap={String(spacing)}
      data-image={picture}
      data-state={still ? "still" : "live"}
      className={cn("relative h-80 w-full overflow-hidden rounded-xl bg-background text-foreground", className)}
    >
      <div
        ref={scrollerRef}
        data-scroller="velocity-bend-gallery"
        data-fallback={still ? "still" : undefined}
        className="absolute inset-0 overflow-y-auto"
        onScroll={onScroll}
      >
        <div className="flex flex-col px-3 py-3" data-track="velocity-bend-gallery" style={{ gap: `${spacing}px` }}>
          {cards.map((card, index) => {
            const src = card.src
            const shot = cardPicture(src, loaded, failed)
            const showPhoto = still && shot === "photo"
            return (
              <article
                key={`${card.title}-${src ?? "stand-in"}-${index}`}
                data-card={index}
                data-image={shot}
                className={cn("relative min-h-36 shrink-0 overflow-hidden rounded-lg border border-border p-4", !still && "opacity-0")}
                style={showPhoto ? undefined : { backgroundImage: `linear-gradient(165deg, var(--background), var(${card.tone}))` }}
              >
                {src ? (
                  <img
                    src={src}
                    alt=""
                    className={showPhoto ? "absolute inset-0 h-full w-full object-cover" : "hidden"}
                    onLoad={() => setLoaded((prev) => remember(prev, src))}
                    onError={() => setFailed((prev) => remember(prev, src))}
                  />
                ) : null}
                <p className="relative text-sm font-medium">{card.title}</p>
              </article>
            )
          })}
        </div>
      </div>
      {still ? null : <canvas ref={canvasRef} aria-hidden className="pointer-events-none absolute inset-0 h-full w-full" />}
    </div>
  )
}

"use client"

/** 设备像素比上限 1.5。0 或空值按 1。 */
export function cappedDpr(dpr: number): number {
  return Math.min(dpr || 1, 1.5)
}

/** 离开视口或页面隐藏时，连续帧停住。 */
export function shouldDrawFrame(inView: boolean, pageVisible: boolean): boolean {
  return inView && pageVisible
}

export type GlContext = WebGL2RenderingContext | WebGLRenderingContext

export interface GlSize {
  cssWidth: number
  cssHeight: number
  width: number
  height: number
  dpr: number
}

export interface GlFrame {
  gl: GlContext
  time: number
  dt: number
  size: GlSize
}

/** 浮点颜色附件是否可渲染。half 为真时用半精度。 */
export interface FloatSupport {
  renderable: boolean
  half: boolean
}

export interface GlTarget {
  framebuffer: WebGLFramebuffer
  texture: WebGLTexture
  width: number
  height: number
}

export interface GlPair {
  read: GlTarget
  write: GlTarget
  swap: () => void
  resize: (width: number, height: number) => void
  dispose: () => void
}

export interface GlLoopHandle {
  gl: GlContext
  floatSupport: FloatSupport
  dispose: () => void
  size: () => GlSize
  createPair: (width: number, height: number) => GlPair | null
  /** 全屏三角形。顶点属性 location 0，名字是 a。 */
  draw: () => void
}

interface TexFormat {
  internal: number
  format: number
  type: number
}

function isGlContext(value: unknown): value is GlContext {
  if (typeof value !== "object" || value === null) return false
  const record = value as { createShader?: unknown; drawArrays?: unknown; getExtension?: unknown }
  return (
    typeof record.createShader === "function" &&
    typeof record.drawArrays === "function" &&
    typeof record.getExtension === "function"
  )
}

function isWebGL2(gl: GlContext): gl is WebGL2RenderingContext {
  return typeof (gl as WebGL2RenderingContext).drawBuffers === "function"
}

function obtainGl(canvas: HTMLCanvasElement): GlContext | null {
  const attrs: WebGLContextAttributes = {
    alpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    premultipliedAlpha: false,
  }
  try {
    const gl2 = canvas.getContext("webgl2", attrs)
    if (isGlContext(gl2)) return gl2
    const gl = canvas.getContext("webgl", attrs)
    if (isGlContext(gl)) return gl
    return null
  } catch {
    return null
  }
}

function byteFormat(gl: GlContext): TexFormat {
  return { internal: gl.RGBA, format: gl.RGBA, type: gl.UNSIGNED_BYTE }
}

function floatFormat(gl: GlContext, support: FloatSupport): TexFormat {
  if (!support.renderable) return byteFormat(gl)
  if (isWebGL2(gl)) {
    if (support.half) return { internal: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT }
    return { internal: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT }
  }
  return { internal: gl.RGBA, format: gl.RGBA, type: gl.FLOAT }
}

function fillTexture(gl: GlContext, texture: WebGLTexture, width: number, height: number, format: TexFormat) {
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  gl.texImage2D(gl.TEXTURE_2D, 0, format.internal, width, height, 0, format.format, format.type, null)
}

function attach(gl: GlContext, framebuffer: WebGLFramebuffer, texture: WebGLTexture) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer)
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0)
  return gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE
}

function probeFormat(gl: GlContext, format: TexFormat): boolean {
  const texture = gl.createTexture()
  const framebuffer = gl.createFramebuffer()
  if (!texture || !framebuffer) {
    if (texture) gl.deleteTexture(texture)
    if (framebuffer) gl.deleteFramebuffer(framebuffer)
    return false
  }
  fillTexture(gl, texture, 1, 1, format)
  const ok = attach(gl, framebuffer, texture)
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  gl.deleteTexture(texture)
  gl.deleteFramebuffer(framebuffer)
  return ok
}

function probeFloat(gl: GlContext): FloatSupport {
  if (!isWebGL2(gl)) {
    const textureFloat = gl.getExtension("OES_texture_float")
    const colorBuffer = gl.getExtension("WEBGL_color_buffer_float")
    if (!textureFloat || !colorBuffer) return { renderable: false, half: false }
    return { renderable: probeFormat(gl, { internal: gl.RGBA, format: gl.RGBA, type: gl.FLOAT }), half: false }
  }
  gl.getExtension("EXT_color_buffer_float")
  if (probeFormat(gl, { internal: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT })) {
    return { renderable: true, half: true }
  }
  if (probeFormat(gl, { internal: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT })) {
    return { renderable: true, half: false }
  }
  return { renderable: false, half: false }
}

function destroyTarget(gl: GlContext, target: GlTarget) {
  gl.deleteFramebuffer(target.framebuffer)
  gl.deleteTexture(target.texture)
}

function createTarget(gl: GlContext, width: number, height: number, support: FloatSupport): GlTarget | null {
  const texture = gl.createTexture()
  const framebuffer = gl.createFramebuffer()
  if (!texture || !framebuffer) {
    if (texture) gl.deleteTexture(texture)
    if (framebuffer) gl.deleteFramebuffer(framebuffer)
    return null
  }
  const w = Math.max(1, Math.floor(width))
  const h = Math.max(1, Math.floor(height))
  const preferred = floatFormat(gl, support)
  fillTexture(gl, texture, w, h, preferred)
  let ok = attach(gl, framebuffer, texture)
  if (!ok && preferred.type !== gl.UNSIGNED_BYTE) {
    fillTexture(gl, texture, w, h, byteFormat(gl))
    ok = attach(gl, framebuffer, texture)
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  if (!ok) {
    gl.deleteTexture(texture)
    gl.deleteFramebuffer(framebuffer)
    return null
  }
  return { framebuffer, texture, width: w, height: h }
}

function resizeTarget(gl: GlContext, target: GlTarget, width: number, height: number, support: FloatSupport) {
  const w = Math.max(1, Math.floor(width))
  const h = Math.max(1, Math.floor(height))
  if (target.width === w && target.height === h) return
  const preferred = floatFormat(gl, support)
  fillTexture(gl, target.texture, w, h, preferred)
  let ok = attach(gl, target.framebuffer, target.texture)
  if (!ok && preferred.type !== gl.UNSIGNED_BYTE) {
    fillTexture(gl, target.texture, w, h, byteFormat(gl))
    ok = attach(gl, target.framebuffer, target.texture)
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  if (ok) {
    target.width = w
    target.height = h
  }
}

function createPair(gl: GlContext, width: number, height: number, support: FloatSupport): GlPair | null {
  const first = createTarget(gl, width, height, support)
  const second = createTarget(gl, width, height, support)
  if (!first || !second) {
    if (first) destroyTarget(gl, first)
    if (second) destroyTarget(gl, second)
    return null
  }
  const pair: GlPair = {
    read: first,
    write: second,
    swap() {
      const next = pair.read
      pair.read = pair.write
      pair.write = next
    },
    resize(nextWidth, nextHeight) {
      resizeTarget(gl, pair.read, nextWidth, nextHeight, support)
      resizeTarget(gl, pair.write, nextWidth, nextHeight, support)
    },
    dispose() {
      destroyTarget(gl, pair.read)
      destroyTarget(gl, pair.write)
    },
  }
  return pair
}

function measureOf(host: HTMLElement, canvas: HTMLCanvasElement): GlSize {
  const rect = host.getBoundingClientRect()
  const cssWidth = Math.max(1, rect.width || host.clientWidth || 1)
  const cssHeight = Math.max(1, rect.height || host.clientHeight || 1)
  const raw = typeof window === "undefined" ? 1 : window.devicePixelRatio
  const dpr = cappedDpr(typeof raw === "number" ? raw : 1)
  const width = Math.max(1, Math.round(cssWidth * dpr))
  const height = Math.max(1, Math.round(cssHeight * dpr))
  if (canvas.width !== width) canvas.width = width
  if (canvas.height !== height) canvas.height = height
  return { cssWidth, cssHeight, width, height, dpr }
}

function createTriangle(gl: GlContext): WebGLBuffer | null {
  const buffer = gl.createBuffer()
  if (!buffer) return null
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
  gl.bindBuffer(gl.ARRAY_BUFFER, null)
  return buffer
}

function releaseContext(gl: GlContext) {
  gl.getExtension("WEBGL_lose_context")?.loseContext()
}

/** 编译失败时删掉着色器并返回 null。 */
export function compileShader(gl: GlContext, type: number, source: string): WebGLShader | null {
  const shader = gl.createShader(type)
  if (!shader) return null
  gl.shaderSource(shader, source)
  gl.compileShader(shader)
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader)
    return null
  }
  return shader
}

function rgbChannels(input: string): [number, number, number] | null {
  const text = input.trim()
  const hex = /^#([\da-f]{3}|[\da-f]{6})$/i.exec(text)
  const body = hex?.[1]
  if (body) {
    const full = body.length === 3 ? [...body].map((char) => char + char).join("") : body
    const value = Number.parseInt(full, 16)
    return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
  }
  const rgb = /^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/i.exec(text)
  if (!rgb?.[1] || !rgb[2] || !rgb[3]) return null
  return [Number(rgb[1]) / 255, Number(rgb[2]) / 255, Number(rgb[3]) / 255]
}

/** hex、rgb 直接解析。其余写进 color，读浏览器算出的 rgb。失败返回 null。 */
export function parseCssColor(host: HTMLElement, input: string): [number, number, number] | null {
  const text = input.trim()
  if (!text) return null
  const direct = rgbChannels(text)
  if (direct) return direct
  const previous = host.style.color
  host.style.color = text
  try {
    return rgbChannels(getComputedStyle(host).color)
  } finally {
    host.style.color = previous
  }
}

/**
 * 多 pass 效果共用的原始 WebGL 循环。只管生命周期：成对 framebuffer、全屏三角形、
 * 浮点纹理探测、像素比上限、尺寸、离屏暂停、卸载时释放 context。
 * getContext 拿不到时返回 null，不抛。
 */
export function mountGlLoop(
  canvas: HTMLCanvasElement,
  options: {
    host: HTMLElement
    frame: (frame: GlFrame) => void
  },
): GlLoopHandle | null {
  const gl = obtainGl(canvas)
  if (!gl) return null
  const triangle = createTriangle(gl)
  if (!triangle) {
    releaseContext(gl)
    return null
  }
  const floatSupport = probeFloat(gl)
  let current = measureOf(options.host, canvas)
  let alive = true
  let raf = 0
  let last = 0
  let inView = true
  let pageVisible = document.visibilityState !== "hidden"
  let observer: IntersectionObserver | null = null
  const context = gl

  function poke() {
    if (!alive || raf !== 0) return
    if (!shouldDrawFrame(inView, pageVisible)) return
    raf = requestAnimationFrame(tick)
  }

  function tick(now: number) {
    raf = 0
    if (!alive || !shouldDrawFrame(inView, pageVisible)) return
    const dt = last === 0 ? 0 : Math.min(0.05, (now - last) / 1000)
    last = now
    current = measureOf(options.host, canvas)
    options.frame({ gl: context, time: now / 1000, dt, size: current })
    if (alive) poke()
  }

  function onVisibility() {
    pageVisible = document.visibilityState !== "hidden"
    poke()
  }

  if (typeof IntersectionObserver === "function") {
    inView = false
    observer = new IntersectionObserver((entries) => {
      const entry = entries[entries.length - 1]
      inView = entry ? entry.isIntersecting : true
      poke()
    })
    observer.observe(options.host)
  }
  document.addEventListener("visibilitychange", onVisibility)
  poke()

  return {
    gl,
    floatSupport,
    size: () => current,
    createPair: (width, height) => (alive ? createPair(gl, width, height, floatSupport) : null),
    draw() {
      if (!alive) return
      gl.bindBuffer(gl.ARRAY_BUFFER, triangle)
      gl.enableVertexAttribArray(0)
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    },
    dispose() {
      if (!alive) return
      alive = false
      if (raf !== 0) cancelAnimationFrame(raf)
      raf = 0
      observer?.disconnect()
      document.removeEventListener("visibilitychange", onVisibility)
      gl.bindBuffer(gl.ARRAY_BUFFER, null)
      gl.deleteBuffer(triangle)
      releaseContext(gl)
    },
  }
}
